// Cvss2Scores returns CVSS V2 Scores
func (v VulnInfo) Cvss2Scores() (values []CveContentCvss) {
	order := append([]CveContentType{RedHatAPI, RedHat, Nvd, Jvn}, GetCveContentTypes("trivy")...)
	for _, ctype := range order {
		if conts, found := v.CveContents[ctype]; found {
			for _, cont := range conts {
				if cont.Cvss2Score == 0 && cont.Cvss2Severity == "" {
					continue
				}
				// https://nvd.nist.gov/vuln-metrics/cvss
				values = append(values, CveContentCvss{
					Type: ctype,
					Value: Cvss{
						Type:     CVSS2,
						Score:    cont.Cvss2Score,
						Vector:   cont.Cvss2Vector,
						Severity: strings.ToUpper(cont.Cvss2Severity),
					},
				})
			}
		}
	}
	return
}

// Cvss3Scores returns CVSS V3 Score
func (v VulnInfo) Cvss3Scores() (values []CveContentCvss) {
	order := []CveContentType{RedHatAPI, RedHat, SUSE, Microsoft, Fortinet, Nvd, Jvn}
	for _, ctype := range order {
		if conts, found := v.CveContents[ctype]; found {
			for _, cont := range conts {
				if cont.Cvss3Score == 0 && cont.Cvss3Severity == "" {
					continue
				}
				// https://nvd.nist.gov/vuln-metrics/cvss
				values = append(values, CveContentCvss{
					Type: ctype,
					Value: Cvss{
						Type:     CVSS3,
						Score:    cont.Cvss3Score,
						Vector:   cont.Cvss3Vector,
						Severity: strings.ToUpper(cont.Cvss3Severity),
					},
				})
			}
		}
	}

	for _, ctype := range append([]CveContentType{Debian, DebianSecurityTracker, Ubuntu, UbuntuAPI, Amazon, Trivy, GitHub, WpScan}, GetCveContentTypes("trivy")...) {
		if conts, found := v.CveContents[ctype]; found {
			for _, cont := range conts {
				if strings.HasPrefix(string(ctype), "trivy:") {
					if cont.Cvss3Score != 0 || cont.Cvss3Severity != "" {
						score := cont.Cvss3Score
						calculated := false
						if score == 0 {
							score = severityToCvssScoreRoughly(cont.Cvss3Severity)
							calculated = true
						}
						values = append(values, CveContentCvss{
							Type: ctype,
							Value: Cvss{
								Type: CVSS3, Score: score, Vector: cont.Cvss3Vector,
								Severity: strings.ToUpper(cont.Cvss3Severity), CalculatedBySeverity: calculated,
							},
						})
					}
					continue
				}
				if cont.Cvss3Severity != "" {
					switch ctype {
					case DebianSecurityTracker: // Multiple Severities(sorted) may be listed, and the largest one is used.
						ss := strings.Split(cont.Cvss3Severity, "|")
						values = append(values, CveContentCvss{
							Type: ctype,
							Value: Cvss{
								Type:                 CVSS3,
								Score:                severityToCvssScoreRoughly(ss[len(ss)-1]),
								CalculatedBySeverity: true,
								Severity:             strings.ToUpper(cont.Cvss3Severity),
							},
						})
					default:
						values = append(values, CveContentCvss{
							Type: ctype,
							Value: Cvss{
								Type:                 CVSS3,
								Score:                severityToCvssScoreRoughly(cont.Cvss3Severity),
								CalculatedBySeverity: true,
								Severity:             strings.ToUpper(cont.Cvss3Severity),
							},
						})
					}
				}
			}
		}
	}

	// Memo: Only RedHat, SUSE, Oracle and Amazon has severity data in advisory.
	for _, adv := range v.DistroAdvisories {
		if adv.Severity != "" {
			score := severityToCvssScoreRoughly(adv.Severity)
			values = append(values, CveContentCvss{
				Type: "Vendor",
				Value: Cvss{
					Type:                 CVSS3,
					Score:                score,
					CalculatedBySeverity: true,
					Severity:             strings.ToUpper(adv.Severity),
				},
			})
		}
	}
	return

